#!/usr/bin/env python3
import subprocess
import sys

# Make the script executable and run it
try:
    subprocess.run(['chmod', '+x', '/tmp/create_i9_form.py'], check=True)
    result = subprocess.run(['python3', '/tmp/create_i9_form.py'], capture_output=True, text=True)
    print(result.stdout)
    if result.stderr:
        print("STDERR:", result.stderr)
except subprocess.CalledProcessError as e:
    print(f"Error running script: {e}")
except Exception as e:
    print(f"Unexpected error: {e}")
